import{H as e,_t as t,it as n,rt as r}from"./chunks/framework.Bcve9O8f.js";var i=JSON.parse(`{"title":"Rights","description":"What this deposit claims under international law, and what it does not — parsed from the sealed proof that the two sets coincide.","frontmatter":{"title":"Rights","description":"What this deposit claims under international law, and what it does not — parsed from the sealed proof that the two sets coincide.","head":[["meta",{"name":"robots","content":"index, follow"}],["meta",{"property":"og:title","content":"Rights | Millennium Solutions"}],["meta",{"property":"og:description","content":"What this deposit claims under international law, and what it does not — parsed from the sealed proof that the two sets coincide."}],["meta",{"property":"og:url","content":"https://ceccec.psg.bg/millennium-solutions/rights.html"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:title","content":"Rights | Millennium Solutions"}],["meta",{"name":"twitter:description","content":"What this deposit claims under international law, and what it does not — parsed from the sealed proof that the two sets coincide."}],["link",{"rel":"canonical","href":"https://ceccec.psg.bg/millennium-solutions/rights.html"}],["link",{"rel":"alternate","hreflang":"en","href":"https://ceccec.psg.bg/millennium-solutions/rights.html"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://ceccec.psg.bg/millennium-solutions/rights.html"}]]},"headers":[],"relativePath":"rights.md","filePath":"rights.md"}`),a={name:`rights.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="rights-—-everything-claimable-and-nothing-else" tabindex="-1">Rights — everything claimable, and nothing else <a class="header-anchor" href="#rights-—-everything-claimable-and-nothing-else" aria-label="Permalink to “Rights — everything claimable, and nothing else”">​</a></h1><p>Author: <strong>Tsvetan Rouschev</strong> · <a href="https://orcid.org/0009-0000-7312-9778" target="_blank" rel="noreferrer">ORCID 0009-0000-7312-9778</a> · licence <code>CC BY-NC-ND 4.0</code>.</p><p>This deposit claims <strong>every right that arises without formality</strong>, and claims nothing that would require an act it has not performed. Berne Art. 5(2) is the hinge: the enjoyment and exercise of these rights are not subject to any formality, so they are held from the moment of authorship whether or not anyone says so. Saying so anyway costs nothing and removes an argument.</p><p>That the claimed set is <em>exactly</em> the without-formality set is not an assertion here — it is decided by the Lean kernel over the whole enumeration, at <a href="/millennium-solutions/theorem/lean_rights_claims_exactly_what_arises_without_formality.html"><code>rights_claims_exactly_what_arises_without_formality</code></a>. Read one way it says no claimable right is abandoned; read the other, that nothing is claimed which is not already held.</p><table><thead><tr><th>uuid</th><th>status</th><th>instrument</th><th>why</th></tr></thead><tbody><tr><td><code>4389d60c-c694</code></td><td><strong>CLAIMED</strong></td><td>copyright in the expression — Berne Art. 5(2), no formality, no notice, no deposit</td><td>held from authorship, no formality</td></tr><tr><td><code>261b594c-c029</code></td><td><strong>CLAIMED</strong></td><td>moral rights: attribution and integrity — Berne Art. 6bis, independent of the economic rights</td><td>held from authorship, no formality</td></tr><tr><td><code>2f3d9ec2-4623</code></td><td><strong>CLAIMED</strong></td><td>sui generis database right in the ledger — Directive 96/9/EC Art. 7, substantial investment in verification</td><td>held from authorship, no formality</td></tr><tr><td><code>deaa7784-ce03</code></td><td>not claimed</td><td>REGISTERED trade mark — Paris Art. 6, Madrid Protocol: a registry grants it, an author cannot</td><td>another body must act — a registry grants it, or a committee awards it</td></tr><tr><td><code>ce36ac04-dc49</code></td><td>not claimed</td><td>patent over these methods — EPC Art. 52(2)(a), mathematical methods as such are excluded</td><td>excluded subject matter</td></tr><tr><td><code>68ad7cd8-0296</code></td><td>not claimed</td><td>property in the mathematics itself — a fact is found, not authored, and carries no author&#39;s right</td><td>not capable of being owned</td></tr><tr><td><code>e07b9280-50de</code></td><td>not claimed</td><td>the AWARD of a Millennium Prize — the Clay Institute grants it under its own rules, on peer-reviewed publication</td><td>another body must act — a registry grants it, or a committee awards it</td></tr><tr><td><code>a6697d40-a893</code></td><td><strong>CLAIMED</strong></td><td>UNREGISTERED mark rights arising from USE — no registry act, so the hinge applies</td><td>held from authorship, no formality</td></tr><tr><td><code>67ebb6a4-9a67</code></td><td><strong>CLAIMED</strong></td><td>standing to submit toward the Millennium Problems, and PRIORITY in whatever is proved — earned by doing and dating the work</td><td>held from authorship, no formality</td></tr></tbody></table><h2 id="what-follows-from-the-5-claimed" tabindex="-1">What follows from the 5 claimed <a class="header-anchor" href="#what-follows-from-the-5-claimed" aria-label="Permalink to “What follows from the 5 claimed”">​</a></h2><p><strong>Attribution and integrity are not waivable here.</strong> Berne Art. 6bis moral rights are independent of the economic rights and survive their transfer. Reuse that strips the author&#39;s name, or that presents a modified deposit as this one, is refused on that ground alone — separately from the licence.</p><p><strong>The ledger is a database, and its investment is the verification.</strong> The sui generis right of Directive 96/9/EC Art. 7 protects substantial investment in obtaining, verifying and presenting contents. Every entry here carries a receipt and is re-decided by the kernel on each build; extraction or re-utilisation of a substantial part is reserved.</p><p><strong>Priority is evidenced, not asserted.</strong> Each release mints an immutable provenance tag and a content address, and the chain of receipts is append-only. That is a record of when, not a right in itself.</p><h2 id="what-is-not-claimed-and-will-not-be" tabindex="-1">What is not claimed, and will not be <a class="header-anchor" href="#what-is-not-claimed-and-will-not-be" aria-label="Permalink to “What is not claimed, and will not be”">​</a></h2><p>No patent is sought over these methods — EPC Art. 52(2)(a) excludes mathematical methods as such, and a claim drafted around that exclusion would be a claim over arithmetic. No property is asserted in the mathematics itself: a fact is found, not authored, and ℤ/9 belongs to nobody. And nothing here touches the seven Millennium Prizes, which are the Clay Mathematics Institute&#39;s to award.</p><p><em>This states what the instruments say, drafted from their texts. It is not legal advice; rights that depend on a registry depend on a lawyer and a registrar, and neither has been engaged.</em></p>`,12)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};